class Solution {
  public int maxLen(int n, int[][] edges, String label) {
    int[] adj = new int[n];
    for (int[] e : edges) {
      adj[e[0]] |= 1 << e[1];
      adj[e[1]] |= 1 << e[0];
    }
    int full = 1 << n;
    boolean[] seen = new boolean[full * n * n];
    int best = 1;
    for (int a = 0; a < n; a++) seen[((1 << a) * n + a) * n + a] = true;
    for (int a = 0; a < n; a++) {
      for (int b = a + 1; b < n; b++) {
        if ((adj[a] >> b & 1) != 0 && label.charAt(a) == label.charAt(b)) {
          seen[(((1 << a) | (1 << b)) * n + a) * n + b] = true;
          best = 2;
        }
      }
    }
    for (int mask = 1; mask < full; mask++) {
      int size = Integer.bitCount(mask);
      for (int a = 0; a < n; a++) {
        if ((mask >> a & 1) == 0) continue;
        for (int b = a; b < n; b++) {
          if ((mask >> b & 1) == 0 || !seen[(mask * n + a) * n + b]) continue;
          best = Math.max(best, size);
          int ca = adj[a] & ~mask;
          for (; ca != 0; ca &= ca - 1) {
            int na = Integer.numberOfTrailingZeros(ca);
            int cb = adj[b] & ~mask & ~(1 << na);
            for (; cb != 0; cb &= cb - 1) {
              int nb = Integer.numberOfTrailingZeros(cb);
              if (label.charAt(na) != label.charAt(nb)) continue;
              int lo = Math.min(na, nb), hi = Math.max(na, nb);
              seen[((mask | 1 << na | 1 << nb) * n + lo) * n + hi] = true;
            }
          }
        }
      }
    }
    return best;
  }
}
